SELECT  FROM logan_http

    app_id = #{appId}
     AND device_id = #{deviceId}
     AND kind = #{kind}
     AND host = #{host}
     AND path = #{path}
     AND err_kind = #{errKind}
     AND status >= #{minStatus}
     AND status <= #{maxStatus}
     AND slow = 1
     AND occurred_at >= #{beginTime}
     AND occurred_at <= #{endTime}

        AND (url LIKE CONCAT('%', #{keyword}, '%') OR err_msg LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY occurred_at DESC LIMIT #{limit}

SELECT  FROM logan_http
WHERE app_id = #{appId} AND device_id = #{deviceId}
  AND occurred_at >= #{beginTime} AND occurred_at <= #{endTime}
ORDER BY occurred_at ASC LIMIT #{limit}

SELECT  FROM logan_http_issue

    app_id = #{appId}
     AND status_flag = #{statusFlag}
     AND kind = #{kind}
     AND err_kind = #{errKind}

ORDER BY last_seen DESC LIMIT #{limit}

mapper.update:
UPDATE logan_http_issue
status_flag = #{statusFlag}, last_fix_note = #{lastFixNote}, reopen_count = #{reopenCount},
WHERE id = #{id}
